def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    if not isinstance(prior, InventoryValidator):
        raise TypeError('Input prior must be an instance of InventoryValidator.')

    if not self.inventory.is_compatible_with(prior.inventory):
        raise ValueError('Current inventory is not compatible with the prior inventory.')

    if not self.inventory.version < prior.inventory.version:
        raise ValueError('Prior inventory version must be greater than the current inventory version.')

    if not self.inventory.data == prior.inventory.data:
        raise ValueError('Current inventory data must be identical to the prior inventory data.')

    return True

