def _explore_folder(folder):
    """
    Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package
    Returns
    -------
    dict
    """
    data_dict = {}
    for root, _, files in os.walk(folder):
        for f in files:
            if f.endswith('.xml'):
                xml_basename = f[:-4]
                if xml_basename not in data_dict:
                    data_dict[xml_basename] = []
                data_dict[xml_basename].append(os.path.join(root, f))
    return {k: v for k, v in data_dict.items()}

