from ruamel.yaml.nodes import ScalarNode, MappingNode

def _merge_nodes(key_node, value_node, existing_value_node):
    if isinstance(value_node, MappingNode) and isinstance(existing_value_node, MappingNode):
        merged_value_node = existing_value_node.fdeep_compare(value_node)
        for key, node in merged_value_node.value:
            if isinstance(key, ScalarNode) and isinstance(node, MappingNode):
                _merge_nodes(key, node, existing_value_node.get(key, None))
        return merged_value_node
    else:
        return value_node

def deep_merge_nodes(nodes):
    merged_nodes = {}
    for key_node, value_node in nodes:
        if key_node.value not in merged_nodes:
            merged_nodes[key_node.value] = (key_node, value_node)
        else:
            existing_key_node, existing_value_node = merged_nodes[key_node.value]
            new_value_node = _merge_nodes(key_node, value_node, existing_value_node)
            merged_nodes[key_node.value] = (key_node, new_value_node)
    return [node for node in merged_nodes.values()]

