def parse_frequency(frequency):
    '''Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    if frequency is None or frequency.lower() == "always":
        return None

    frequency = frequency.lower()
    frequency_map = {
        'seconds': lambda x: datetime.timedelta(seconds=x),
        'minutes': lambda x: datetime.timedelta(minutes=x),
        'hours': lambda x: datetime.timedelta(hours=x),
        'days': lambda x: datetime.timedelta(days=x),
        'weeks': lambda x: datetime.timedelta(weeks=x),
        'months': lambda x: datetime.timedelta(days=x * 30),
        'years': lambda x: datetime.timedelta(days=x * 365)
    }

    for unit, time_delta_func in frequency_map.items():
        if frequency.endswith(unit):
            try:
                value = int(frequency[:-len(unit)].strip())
                return time_delta_func(value)
            except ValueError:
                pass

    raise ValueError(f'Invalid frequency: {frequency}')

