from datetime import datetime, timedelta, time, timezone

class Time:
    @classmethod
    def from_ticks(cls, ticks, tz=None):
        """Create a time from ticks (nanoseconds since midnight).

        :param ticks: nanoseconds since midnight
        :type ticks: int
        :param tz: optional timezone
        :type tz: datetime.tzinfo

        :rtype: Time

        :raises ValueError: if ticks is out of bounds
            (0 <= ticks < 86400000000000)
        """
        if not (0 <= ticks < 86400000000000):
            raise ValueError("Ticks out of bounds")

        seconds = ticks // 1_000_000_000
        nanoseconds = ticks % 1_000_000_000

        td = timedelta(seconds=seconds, microseconds=nanoseconds // 1_000)
        t = time(td.seconds % (24 * 3600), td.seconds // 3600, td.microseconds // 1_000)

        if tz:
            dt = datetime.combine(datetime.min, t).replace(tzinfo=tz)
            return Time(dt, tz)
        return Time(t, tz)

    def __init__(self, time, tz):
        self._time = time
        self._tz = tz

    @property
    def time(self):
        return self._time

    @property
    def tz(self):
        return self._tz

